import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

// Books live in memory and every change is written straight to a JSON file.
// Writes go to a temp file first and are then renamed over the real one, so a
// crash mid-write can't leave a half-written books.json behind.
export function createStore(filePath) {
  let books = load(filePath);

  function save(next) {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    const tmp = `${filePath}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(next, null, 2) + '\n');
    fs.renameSync(tmp, filePath);
    // Only swap the in-memory copy once the file is safely on disk.
    books = next;
  }

  function newId() {
    let id;
    do {
      id = crypto.randomBytes(6).toString('base64url');
    } while (books.some((b) => b.id === id));
    return id;
  }

  return {
    all() {
      return books.map((b) => ({ ...b }));
    },

    get(id) {
      const book = books.find((b) => b.id === id);
      return book ? { ...book } : null;
    },

    add({ title, author, notes = '' }) {
      const book = {
        id: newId(),
        title,
        author,
        notes,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      save([...books, book]);
      return { ...book };
    },

    finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      if (book.finishedAt) return { ...book };
      const finished = { ...book, finishedAt: new Date().toISOString() };
      save(books.map((b) => (b.id === id ? finished : b)));
      return { ...finished };
    },
  };
}

function load(filePath) {
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // Refuse to start on a broken file rather than silently replacing it with an
  // empty list on the next save.
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`Could not read ${filePath}: ${err.message}`);
  }
  if (!Array.isArray(data)) {
    throw new Error(`Could not read ${filePath}: expected a JSON array of books`);
  }
  return data;
}

