import { homePage, bookPage, notFoundPage } from './views.js';

const MAX_BODY_BYTES = 100 * 1024;
const MAX_TITLE = 300;
const MAX_AUTHOR = 300;
const MAX_NOTES = 20_000;

export function createApp(store) {
  return async function handle(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      if (err.status) {
        send(res, err.status, err.message, 'text/plain; charset=utf-8');
      } else {
        console.error(err);
        send(res, 500, 'Something went wrong.', 'text/plain; charset=utf-8');
      }
    }
  };
}

async function route(store, req, res) {
  const url = new URL(req.url, 'http://localhost');
  const parts = url.pathname.split('/').filter(Boolean);

  // GET /
  if (parts.length === 0) {
    if (req.method !== 'GET') return methodNotAllowed(res, 'GET');
    return send(res, 200, homePage(store.all()));
  }

  if (parts[0] !== 'books') return send(res, 404, notFoundPage());

  // POST /books
  if (parts.length === 1) {
    if (req.method !== 'POST') return methodNotAllowed(res, 'POST');
    const form = await readForm(req);
    const values = {
      title: form.get('title')?.trim() ?? '',
      author: form.get('author')?.trim() ?? '',
      notes: form.get('notes')?.trim() ?? '',
    };
    const error = validate(values);
    if (error) return send(res, 400, homePage(store.all(), { error, values }));
    const book = store.add(values);
    return redirect(res, `/books/${encodeURIComponent(book.id)}`);
  }

  const id = parts[1];
  const bookPath = `/books/${encodeURIComponent(id)}`;

  // GET /books/:id
  if (parts.length === 2) {
    if (req.method !== 'GET') return methodNotAllowed(res, 'GET');
    const book = store.get(id);
    if (!book) return send(res, 404, notFoundPage());
    const shareUrl = `http://${req.headers.host ?? 'localhost'}${bookPath}`;
    return send(res, 200, bookPage(book, shareUrl));
  }

  // POST /books/:id/finish
  if (parts.length === 3 && parts[2] === 'finish') {
    if (req.method !== 'POST') return methodNotAllowed(res, 'POST');
    const form = await readForm(req);
    if (!store.finish(id)) return send(res, 404, notFoundPage());
    // Only ever send people back to the list or this book's page.
    const next = form.get('next') === '/' ? '/' : bookPath;
    return redirect(res, next);
  }

  return send(res, 404, notFoundPage());
}

function validate({ title, author, notes }) {
  if (!title) return 'Please give the book a title.';
  if (!author) return 'Please say who wrote it.';
  if (title.length > MAX_TITLE) return `Title must be at most ${MAX_TITLE} characters.`;
  if (author.length > MAX_AUTHOR) return `Author must be at most ${MAX_AUTHOR} characters.`;
  if (notes.length > MAX_NOTES) return `Notes must be at most ${MAX_NOTES} characters.`;
  return null;
}

async function readForm(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw httpError(413, 'Request too large.');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function httpError(status, message) {
  return Object.assign(new Error(message), { status });
}

function send(res, status, body, type = 'text/html; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function methodNotAllowed(res, allow) {
  res.writeHead(405, { Allow: allow, 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Method not allowed.');
}

