import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createStore } from '../src/store.js';

let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'books-'));
  file = path.join(dir, 'nested', 'books.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('store', () => {
  it('starts empty when the file does not exist', () => {
    expect(createStore(file).all()).toEqual([]);
  });

  it('keeps books across restarts', () => {
    const first = createStore(file);
    const book = first.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
    first.finish(book.id);

    const second = createStore(file);
    const reloaded = second.get(book.id);
    expect(reloaded).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
    expect(reloaded.finishedAt).toEqual(expect.any(String));
  });

  it('does not change finishedAt when finishing twice', () => {
    const store = createStore(file);
    const book = store.add({ title: 'Emma', author: 'Jane Austen' });
    const once = store.finish(book.id);
    const twice = store.finish(book.id);
    expect(twice.finishedAt).toBe(once.finishedAt);
  });

  it('returns null for unknown books', () => {
    const store = createStore(file);
    expect(store.get('nope')).toBeNull();
    expect(store.finish('nope')).toBeNull();
  });

  it('refuses to load a corrupt file instead of overwriting it', () => {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, '{ not json');
    expect(() => createStore(file)).toThrow(/Could not read/);
    expect(fs.readFileSync(file, 'utf8')).toBe('{ not json');
  });

  it('does not let callers mutate stored books', () => {
    const store = createStore(file);
    const book = store.add({ title: 'Emma', author: 'Jane Austen' });
    book.title = 'Changed';
    store.all()[0].title = 'Changed';
    expect(store.get(book.id).title).toBe('Emma');
  });
});

