import fs from 'node:fs';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createStore } from '../src/store.js';
import { createApp } from '../src/app.js';

let dir;
let file;
let server;
let base;

async function start() {
  server = http.createServer(createApp(createStore(file)));
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((resolve) => server.close(resolve));
}

function post(pathname, fields) {
  return fetch(base + pathname, {
    method: 'POST',
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

async function addBook(fields) {
  const res = await post('/books', fields);
  expect(res.status).toBe(303);
  return res.headers.get('location');
}

beforeEach(async () => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'books-app-'));
  file = path.join(dir, 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('app', () => {
  it('shows empty sections on first visit', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('adds a book and shows it on its own page', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Line one\nLine two' });
    expect(location).toMatch(/^\/books\/[\w-]+$/);

    const res = await fetch(base + location);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<h2>Dune</h2>');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Line one\nLine two');
    expect(html).toContain(`value="${base}${location}"`);

    const home = await (await fetch(base + '/')).text();
    const reading = home.split('<h2>Finished</h2>')[0];
    expect(reading).toContain('Dune');
  });

  it('moves a book to finished', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' });

    const res = await post(`${location}/finish`, { next: '/' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const home = await (await fetch(base + '/')).text();
    const [reading, finished] = home.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Dune');
    expect(finished).toContain('Dune');

    const page = await (await fetch(base + location)).text();
    expect(page).toContain('Finished ');
    expect(page).not.toContain('Mark finished');
  });

  it('only redirects to known pages after finishing', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' });
    const res = await post(`${location}/finish`, { next: 'https://evil.example' });
    expect(res.headers.get('location')).toBe(location);
  });

  it('rejects a book without a title or author and keeps what was typed', async () => {
    const res = await post('/books', { title: '  ', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please give the book a title.');
    expect(html).toContain('value="Someone"');
    expect(html).toContain('>kept</textarea>');

    const noAuthor = await post('/books', { title: 'Dune' });
    expect(noAuthor.status).toBe(400);
    expect(createStore(file).all()).toEqual([]);
  });

  it('escapes user input', async () => {
    const location = await addBook({
      title: '<script>alert(1)</script>',
      author: '"><img src=x>',
      notes: '</div><b>hi</b>',
    });
    for (const html of [
      await (await fetch(base + location)).text(),
      await (await fetch(base + '/')).text(),
    ]) {
      expect(html).not.toContain('<script>alert(1)</script>');
      expect(html).not.toContain('<img src=x>');
      expect(html).not.toContain('<b>hi</b>');
      expect(html).toContain('&lt;script&gt;');
    }
  });

  it('keeps books after a restart', async () => {
    const location = await addBook({ title: 'Emma', author: 'Jane Austen' });
    await stop();
    await start();
    const res = await fetch(base + location);
    expect(res.status).toBe(200);
    expect(await res.text()).toContain('Emma');
  });

  it('returns 404 for unknown books and pages', async () => {
    expect((await fetch(base + '/books/missing')).status).toBe(404);
    expect((await post('/books/missing/finish', {})).status).toBe(404);
    expect((await fetch(base + '/elsewhere')).status).toBe(404);
  });

  it('returns 405 for the wrong method', async () => {
    expect((await fetch(base + '/books')).status).toBe(405);
    expect((await post('/', {})).status).toBe(405);
  });

  it('rejects oversized requests', async () => {
    const res = await post('/books', { title: 'x', author: 'y', notes: 'z'.repeat(200 * 1024) });
    expect(res.status).toBe(413);
  });
});

